    @Test("file-system-compressed")
    func fileSystemCompressed() async throws {
        let data: Uint8Array = await TestPlatformPartials.loadFile("test-data/guitarpro6/file-system-compressed.gpx")
        let fileSystem: GpxFileSystem = GpxFileSystem()
        try fileSystem.load(ByteBuffer.fromBuffer(data))
        let names: List<String> = List<String>("score.gpif", "misc.xml", "BinaryStylesheet", "PartConfiguration", "LayoutConfiguration")
        let sizes: List<Double> = List<Double>(8488.0, 130.0, 12204.0, 20.0, 12.0)
        do {
            var i: Double = 0.0
            while i < fileSystem.files.length {
                let file: GpxFile = fileSystem.files[(i).toInt()]
                Logger.info("Test", "\((file.fileName).toTemplate()) - \((file.fileSize).toTemplate())")
                TestGlobals.expect(file.fileName).toBe(names[(i).toInt()])
                TestGlobals.expect(file.fileSize).toBe(sizes[(i).toInt()])
                i += 1
            }
        }
    }

